{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    edges = []
    for n1, n2, d in dists:
        w = max(core[n1], core[n2], d)
        a, b = (n1, n2) if n1 <= n2 else (n2, n1)
        edges.append((a, b, w))
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {}
    rank = {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    for n in nodes:
        parent[n] = n
        rank[n] = 0
    mst_edges = []
    total = 0.0
    for a, b, w in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total += w
            if len(mst_edges) == len(nodes) - 1:
                break
    return {'mst_edges': mst_edges, 'total_weight': total}"
}
